/*
 * Front <-> core interface. A front (gen/<SONAME>.S + gen/<SONAME>_table.c)
 * passes one struct nvg_front to nvg_front_init() from its .init_array.
 * Generated by tools/gen-fronts.py; keep NVG_FRONT_ABI in sync with it.
 */
#pragma once

#define NVG_FRONT_MAGIC 0x6e76676cu /* "nvgl" */
#define NVG_FRONT_ABI 1

enum nvg_lib { NVG_LIB_LIBC = 0, NVG_LIB_LIBM = 1, NVG_LIB_LIBDL = 2, NVG_LIB_CORE = 3 };

enum nvg_kind {
    NVG_KIND_SLOT = 0, /* `jmp *slot`: slot <- dlsym(bionic lib, target) */
    NVG_KIND_CORE = 1, /* `jmp nvg_<name>@PLT`: nothing to fill */
    NVG_KIND_DATA = 2, /* 8-byte object: *slot <- *(void **)dlsym(bionic lib, target) */
};

struct nvg_front_sym {
    const char *name;    /* exported glibc name */
    const char *target;  /* bionic name (SLOT, DATA) or nvg_<name> (CORE) */
    void **slot;         /* SLOT: the trampoline's slot; DATA: the exported object */
    void *addr;          /* address of the front's exported definition */
    unsigned char lib;   /* enum nvg_lib */
    unsigned char kind;  /* enum nvg_kind */
};

struct nvg_front {
    unsigned magic;
    unsigned abi;
    const char *soname;
    unsigned nsyms;
    const struct nvg_front_sym *syms;
};
